def emit_tax_events(bus, quote, tax_bps):
    net = int(quote['net_cents'])
    tax = (net * int(tax_bps)) // 10000
    gross = net + tax
    bus.publish('tax_escrow', tax, causal_index=2)
    return {'net_cents': net, 'tax_cents': tax, 'gross_cents': gross}

